bruteForceSolution.code:
function patternSquare(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < n; j++) {
      row += '*';
    }
    rows.push(row);
  }
  return rows.join('\n');
}

